css:
@property --dl { syntax: "<angle>"; inherits: false; initial-value: 180deg; }@property --rp { syntax: "<number>"; inherits: true; initial-value: 0; }@property --fl { syntax: "<percentage>"; inherits: true; initial-value: 0%; }@keyframes swvS { 
  100% { rotate: var(--wv,20deg); }
}@keyframes swcW { 
  0% { translate: 0px; }
  12.5% { translate: 0 calc(var(--ca)*.7071); }
  25% { translate: 0 var(--ca); }
  37.5% { translate: 0 calc(var(--ca)*.7071); }
  50% { translate: 0px; }
  62.5% { translate: 0 calc(var(--ca)*-.7071); }
  75% { translate: 0 calc(var(--ca)*-1); }
  87.5% { translate: 0 calc(var(--ca)*-.7071); }
  100% { translate: 0px; }
}
